from zipfile import ZipFile, ZIP_DEFLATED
from lxml import etree
from copy import deepcopy
import re, shutil, os

W='http://schemas.openxmlformats.org/wordprocessingml/2006/main'
NS={'w':W}
qn=lambda tag: f'{{{W}}}{tag}'
xml_space='{http://www.w3.org/XML/1998/namespace}space'

def accept_revisions(root):
    # Remove deleted/moved-from content, then unwrap inserted/moved-to content.
    for tag in ['del','moveFrom']:
        for el in list(root.xpath('.//w:'+tag, namespaces=NS)):
            par=el.getparent()
            if par is not None: par.remove(el)
    for tag in ['ins','moveTo']:
        for el in list(root.xpath('.//w:'+tag, namespaces=NS)):
            par=el.getparent()
            if par is None: continue
            idx=par.index(el)
            for child in list(el):
                par.insert(idx, child); idx += 1
            par.remove(el)

def normalize_markers(text):
    # Draft 2 contains legacy literal markup labels in addition to OOXML revisions.
    # Keep added text and drop deleted text.
    prev=None
    while prev != text:
        prev=text
        text=re.sub(r'\[(?:DELETED|ADDED):\s*(.*?)\]', lambda m: '' if m.group(0).startswith('[DELETED:') else m.group(1), text, flags=re.S)
    return text

def normalize_paragraphs(root):
    for p in root.xpath('.//w:p', namespaces=NS):
        texts=[]
        for t in p.xpath('.//w:t', namespaces=NS):
            texts.append(t.text or '')
        # retain literal tabs as a space if any; this agreement uses paragraph/table formatting
        text=normalize_markers(''.join(texts))
        pPr=p.find(qn('pPr'))
        first_r=p.find(qn('r'))
        rPr=deepcopy(first_r.find(qn('rPr'))) if first_r is not None and first_r.find(qn('rPr')) is not None else None
        for child in list(p):
            if child is not pPr:
                p.remove(child)
        if text:
            r=etree.Element(qn('r'))
            if rPr is not None: r.append(rPr)
            t=etree.SubElement(r, qn('t'))
            t.text=text
            if text[:1].isspace() or text[-1:].isspace(): t.set(xml_space,'preserve')
            p.append(r)

def process_doc(src, dst):
    with ZipFile(src) as zin:
        files={n:zin.read(n) for n in zin.namelist()}
    root=etree.fromstring(files['word/document.xml'])
    accept_revisions(root)
    normalize_paragraphs(root)
    files['word/document.xml']=etree.tostring(root, xml_declaration=True, encoding='UTF-8', standalone='yes')
    with ZipFile(dst,'w',ZIP_DEFLATED) as zout:
        for n,data in files.items(): zout.writestr(n,data)

